contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        // Read before-values
        uint beforeReported = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBal = address(c).balance;
        // Call addToBalance with amount and catch revert
        bool reverted;
        c.addToBalance{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint afterReported = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBal = address(c).balance;
        // General rule: if reverted then no change; otherwise both values do not decrease
        assert(reverted ? (afterReported == beforeReported && afterContractBal == beforeContractBal)
                        : (afterReported >= beforeReported && afterContractBal >= beforeContractBal));
    }
    receive() external payable { }
}

