// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 beforeReported;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeReported = __r; } catch { return; }
        uint beforeContractBal = address(c).balance;
        bool reverted;
        try c.addToBalance{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterReported;
        try c.getBalance(address(this)) returns (uint256 __r) { afterReported = __r; } catch { return; }
        uint afterContractBal = address(c).balance;
        assertTrue(reverted ? (afterReported == beforeReported && afterContractBal == beforeContractBal)
                        : (afterReported >= beforeReported && afterContractBal >= beforeContractBal));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable { }
}
